const raw = $input.first().json;
const b = raw.body || raw;
if (!b || b.type !== 'checkout.session.completed') return [];
const s = (b.data || {}).object || {};
if (s.payment_link !== 'plink_1UJI6EIS4aUrWHCx5vvMB20F') return [];
if (s.payment_status !== 'paid' || s.livemode !== true) return [];
const cd = s.customer_details || {};
const cfs = s.custom_fields || [];
let category = '';
for (const f of cfs) { if (f.key === 'category' && f.text) category = String(f.text.value || '').trim(); }
const businessName = String(cd.business_name || cd.individual_name || cd.name || '').trim();
const d = String(cd.phone || '').replace(/\D/g, '').slice(-10);
return [{ json: {
  sessionId: s.id,
  paymentIntent: s.payment_intent || '',
  paymentUrl: s.payment_intent ? 'https://dashboard.stripe.com/payments/' + s.payment_intent : 'https://dashboard.stripe.com/checkout/sessions/' + s.id,
  amount: (s.amount_total || 0) / 100,
  businessName: businessName,
  nameKey: businessName.toLowerCase().replace(/[^a-z0-9]/g, ''),
  contactName: String(cd.individual_name || cd.name || '').trim(),
  firstName: String(cd.individual_name || cd.name || '').trim().split(' ')[0] || 'there',
  email: String(cd.email || '').toLowerCase(),
  phone: d.length === 10 ? '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6) : String(cd.phone || ''),
  phoneDigits: d,
  category: category,
  paidAt: new Date((s.created || Math.floor(Date.now() / 1000)) * 1000).toISOString().slice(0, 10)
} }];

const inp = $('Parse Paid Checkout').first().json;
const rows = $input.all().map(function (i) { return i.json; });
const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); };
const digits = function (s) { return String(s || '').replace(/\D/g, '').slice(-10); };
const val = function (r, key) { return r[key] !== undefined && r[key] !== null ? r[key] : ''; };
let match = null;
for (const r of rows) { const e = String(val(r, 'property_customer_email')).toLowerCase(); if (inp.email && e && e === inp.email) { match = r; break; } }
if (!match) for (const r of rows) { const p = digits(val(r, 'property_phone')); if (inp.phoneDigits && p && p === inp.phoneDigits) { match = r; break; } }
if (!match) for (const r of rows) {
  const n = norm(r.name || val(r, 'property_business_name'));
  if (n && inp.nameKey && n.length >= 5 && inp.nameKey.length >= 5 && (n === inp.nameKey || n.indexOf(inp.nameKey) >= 0 || inp.nameKey.indexOf(n) >= 0)) { match = r; break; }
}
if (match && String(val(match, 'property_stripe_payment')).indexOf(inp.paymentIntent || inp.sessionId) >= 0) return [];
const paidStages = ['Paid', 'Ad received', 'Ad approved'];
const paidRows = rows.filter(function (r) { return paidStages.indexOf(String(val(r, 'property_sale_stage'))) >= 0; });
const alreadyPaid = match && paidStages.indexOf(String(val(match, 'property_sale_stage'))) >= 0;
const paidCount = paidRows.length + (alreadyPaid ? 0 : 1);
const catKey = norm(inp.category).replace(/s$/, '');
const conflicts = paidRows.filter(function (r) {
  if (match && r.id === match.id) return false;
  const a = norm(val(r, 'property_niche')).replace(/s$/, '');
  const c = norm(val(r, 'property_category')).replace(/s$/, '');
  return catKey.length >= 4 && ((a && (a.indexOf(catKey) >= 0 || catKey.indexOf(a) >= 0)) || (c && (c.indexOf(catKey) >= 0 || catKey.indexOf(c) >= 0)));
}).map(function (r) { return r.name || val(r, 'property_business_name'); });
const props = {
  'Sale Stage': { select: { name: 'Paid' } },
  'Paid Date': { date: { start: inp.paidAt } },
  'Customer Email': { email: inp.email || null },
  'Stripe Payment': { url: inp.paymentUrl }
};
const note = 'Paid $' + inp.amount + ' via Stripe on ' + inp.paidAt + '. Contact: ' + inp.contactName + ', ' + inp.phone + '. Category entered at checkout: ' + inp.category;
const createProps = Object.assign({}, props, {
  'Business Name': { title: [{ text: { content: inp.businessName || 'Unknown business' } }] },
  'Phone': { phone_number: inp.phone || null },
  'Call Notes': { rich_text: [{ text: { content: note + '. Created automatically, not matched to an existing Call List row.' } }] }
});
return [{ json: {
  found: !!match,
  pageId: match ? match.id : '',
  pageUrl: match ? match.url : '',
  updateBody: { properties: props },
  createBody: { parent: { database_id: '5db44cc8-35d1-451e-bb69-2cd2ab6ffc3e' }, properties: createProps },
  paidCount: paidCount,
  conflicts: conflicts,
  inp: inp
} }];
